import { Component, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { finalize } from 'rxjs/operators';

interface AppConfig {
    vectorStorePath: string;
    keywordIndexPath: string;
}

@Component({
    selector: 'app-settings',
    templateUrl: './settings.component.html',
    styleUrls: ['./settings.component.css'],
    standalone: false
})
export class SettingsComponent implements OnInit {
    config: AppConfig = {
        vectorStorePath: '',
        keywordIndexPath: ''
    };
    isLoading = false;
    saveMessage: string | null = null;
    restartRequired = false;

    constructor(private http: HttpClient) { }

    ngOnInit() {
        this.loadConfig();
    }

    loadConfig() {
        this.isLoading = true;
        this.http.get<AppConfig>('/api/config/k-app')
            .pipe(finalize(() => this.isLoading = false))
            .subscribe({
                next: (data) => {
                    this.config = data;
                },
                error: (err) => {
                    console.error('Failed to load settings', err);
                }
            });
    }

    saveSettings() {
        this.isLoading = true;
        this.saveMessage = null;
        this.restartRequired = false;

        // Only save vector store paths here. 
        // Subprocess and Batch config are handled by their own components.
        // We keep the fields in AppConfig for now to avoid breaking the interface, 
        // but we only care about paths here.
        this.http.put<{
            vectorStorePath: string,
            keywordIndexPath: string,
            switched: boolean,
            restartRequired: boolean,
            message: string
        }>('/api/config/k-app', this.config)
            .pipe(finalize(() => this.isLoading = false))
            .subscribe({
                next: (response) => {
                    this.config.vectorStorePath = response.vectorStorePath;
                    this.config.keywordIndexPath = response.keywordIndexPath;

                    this.saveMessage = response.message;
                    this.restartRequired = response.restartRequired;

                    // Clear message after 5 seconds
                    setTimeout(() => {
                        this.saveMessage = null;
                    }, 5000);
                },
                error: (err) => {
                    console.error('Failed to save settings', err);
                    this.saveMessage = 'Failed to save settings. Please check server logs.';
                    this.restartRequired = false;
                }
            });
    }
}
